<template><main class="login"><section class="login-panel"><p class="eyebrow">SMART ESTATE</p><h1>智慧社区物业管理系统</h1><p>请使用演示账户登录，体验业主、物业和管理员工作流。</p><el-form @submit.prevent="submit"><el-form-item label="手机号"><el-input v-model="phone"/></el-form-item><el-form-item label="密码"><el-input v-model="password" type="password" show-password/></el-form-item><el-alert title="演示账户：13800000001（业主）/ 13800000002（物业）/ 13800000003（管理员）；密码均为 password123" type="info" :closable="false"/><el-button class="login-button" type="primary" native-type="submit" :loading="loading">登录系统</el-button></el-form></section></main></template><script setup lang="ts">import{ref}from'vue';import{useRouter}from'vue-router';import{ElMessage}from'element-plus';import{signIn}from'../stores/authStore';const phone=ref('13800000002'),password=ref('password123'),loading=ref(false),router=useRouter();async function submit(){loading.value=true;try{await signIn(phone.value,password.value);router.push('/dashboard')}catch(e){ElMessage.error((e as Error).message)}finally{loading.value=false}}</script>
